51	export function parseToolArguments(call: ToolCall): { args: any; structurallyRepaired: boolean } {
52	  const toolName = call.function.name;
53	  let args: any = {};
54	  let structurallyRepaired = (call as any).repaired === "structural";
55	
56	  try {
57	    args =
58	      typeof call.function.arguments === "string"
59	        ? JSON.parse(call.function.arguments)
60	        : call.function.arguments;
61	  } catch {
62	    if (typeof call.function.arguments === "string") {
63	      try {
64	        const { value, repaired } = repairJsonWithClass(call.function.arguments);
65	        if (repaired === "structural") structurallyRepaired = true;
66	        args = value && typeof value === "object" ? value : { raw: call.function.arguments };
67	      } catch {
68	        structurallyRepaired = true;
69	        args = toolName === "task_completed" ? {} : { raw: call.function.arguments };
70	      }
71	    } else {
72	      args = toolName === "task_completed" ? {} : { raw: call.function.arguments };
73	    }
74	  }
75	
76	  return { args, structurallyRepaired };
77	}
