80	export function admitToolCall(
81	  this: any,
82	  call: ToolCall,
83	  currentStep: number,
84	  actor: "agent" | "subagent",
85	  toolName: string,
86	  args: any,
87	  structurallyRepaired: boolean,
88	): { args: any } | { receipt: ExecutionReceipt; shouldExit: boolean } {
89	  if (structurallyRepaired && isWriteOrExecTool(toolName)) {
90	    return {
91	      receipt: {
92	        invocationId: call.id,
93	        taskId: this.activeWorktree?.taskId || this.currentTaskId,
94	        actor,
95	        executionDomain: actor === "subagent" ? "subagent" : "agent_orchestration",
96	        capabilityId: this.capabilityRegistry.getByToolName(toolName)?.id || toolName,
97	        toolName,
98	        targetResources: [],
99	        success: false,
100	        output: "",
101	        error: `Tool call "${toolName}" rejected: arguments required structural JSON repair (truncated or unclosed string/bracket). Re-issue the call with complete valid JSON arguments.`,
102	        durationMs: 0,
103	        candidateMutated: false,
104	        status: "DENIED",
105	        timestamp: new Date().toISOString(),
106	        simulated: Boolean(this.config.dryRun),
107	      },
108	      shouldExit: false,
109	    };
110	  }
111	
112	  args = normalizeToolArguments(toolName, args, this.getEffectiveTools());
113	
114	  const skillAttr = () => this.skillActivations?.attribution?.() ?? {};
115	  const recordReceipt = (receipt: ExecutionReceipt) => {
116	    this.lastToolReceipts = [...(this.lastToolReceipts || []), receipt].slice(-32);
117	    return receipt;
118	  };
119	
120	  // Delegated authority is checked at the dispatcher as well as when schemas are built. This is the
121	  // enforcement point for malformed/native/text tool calls and extension tools alike.
122	  if (this.delegatedToolAllowList && !this.delegatedToolAllowList.has(toolName)) {
123	    return {
124	      receipt: recordReceipt({
125	        invocationId: call.id,
126	        taskId: this.activeWorktree?.taskId || this.currentTaskId,
127	        actor,
128	        executionDomain: actor === "subagent" ? "subagent" : "agent_orchestration",
129	        capabilityId: this.capabilityRegistry.getByToolName(toolName)?.id || toolName,
130	        toolName,
131	        targetResources: extractTargetResources(toolName, args),
132	        success: false,
133	        output: "",
134	        error: `Delegation authority denied tool '${toolName}'.`,
135	        durationMs: 0,
136	        candidateMutated: false,
137	        status: "DENIED",
138	        denialReason: "DELEGATION_AUTHORITY",
139	        timestamp: new Date().toISOString(),
140	        simulated: Boolean(this.config.dryRun),
141	        ...skillAttr(),
142	      }),
143	      shouldExit: false,
144	    };
145	  }
146	
147	  // A restricted role is refused any tool outside its allow-list, whatever the model was told or claims. A write or
148	  // exec call in read-only mode is left to the read-only check, which refuses it with its own reason.
149	  const roleAllowed = roleToolAllowList(this.role);
150	  const roleDenied = roleToolDenyList(this.role);
151	  const denyListed = Boolean(roleDenied?.has(toolName));
152	  if (denyListed || (roleAllowed && !roleAllowed.has(toolName) && !(this.isReadOnly() && isWriteOrExecTool(toolName)))) {
153	    return {
154	      receipt: recordReceipt({
155	        invocationId: call.id,
156	        taskId: this.activeWorktree?.taskId || this.currentTaskId,
157	        actor,
158	        executionDomain: actor === "subagent" ? "subagent" : "agent_orchestration",
159	        capabilityId: this.capabilityRegistry.getByToolName(toolName)?.id || toolName,
160	        toolName,
161	        targetResources: [],
162	        success: false,
163	        output: "",
164	        error: denyListed
165	          ? `Tool "${toolName}" is not available to role '${this.role}': tools that reach outside the task (${[...roleDenied!].join(", ")}) are not part of that role. Do the work with the tools you have, or report what you could not do.`
166	          : `Tool "${toolName}" is not permitted for role '${this.role}'. Permitted tools: ${[...roleAllowed!].join(", ")}.`,
167	        durationMs: 0,
168	        candidateMutated: false,
169	        status: "DENIED",
170	        timestamp: new Date().toISOString(),
171	        simulated: Boolean(this.config.dryRun),
172	        ...skillAttr(),
173	      }),
174	      shouldExit: false,
175	    };
176	  }
177	
178	  // WP-GS-03: optional skill constraint intersection (never expands session authority).
179	  if (toolName !== "activate_skill" && skillConstraintsEnabled()) {
180	    const cur = this.skillActivations?.current?.();
181	    if (cur && !resolveSkillToolAllowed(toolName, cur.constraints)) {
182	      return {
183	        receipt: recordReceipt({
184	          invocationId: call.id,
185	          taskId: this.activeWorktree?.taskId || this.currentTaskId,
186	          actor,
187	          executionDomain: actor === "subagent" ? "subagent" : "agent_orchestration",
188	          capabilityId: this.capabilityRegistry.getByToolName(toolName)?.id || toolName,
189	          toolName,
190	          targetResources: extractTargetResources(toolName, args),
191	          success: false,
192	          output: "",
193	          error: `Skill constraint denied: tool '${toolName}' is not permitted while skill '${cur.skillName}' is active.`,
194	          durationMs: 0,
195	          candidateMutated: false,
196	          status: "DENIED",
197	          denialReason: "SKILL_CONSTRAINT",
198	          timestamp: new Date().toISOString(),
199	          simulated: Boolean(this.config.dryRun),
200	          ...skillAttr(),
201	        }),
202	        shouldExit: false,
203	      };
204	    }
205	  }
206	
207	  // WP-GS-02 live integrity: block tools if activated skill file drifted.
208	  if (toolName !== "activate_skill" && skillIntegrityMode() === "live") {
209	    const cur = this.skillActivations?.current?.();
210	    if (cur) {
211	      const check = this.skillActivations.liveIntegrityBlocked(() => {
212	        try {
213	          const raw = fs.readFileSync(cur.sourcePath, "utf8");
214	          const close = raw.indexOf("\n---", 3);
215	          if (raw.startsWith("---") && close > 0) return raw.slice(close + 4).trim();
216	          return raw.trim();
217	        } catch {
218	          return null;
219	        }
220	      });
221	      if (check.blocked) {
222	        return {
223	          receipt: recordReceipt({
224	            invocationId: call.id,
225	            taskId: this.activeWorktree?.taskId || this.currentTaskId,
226	            actor,
227	            executionDomain: actor === "subagent" ? "subagent" : "agent_orchestration",
228	            capabilityId: this.capabilityRegistry.getByToolName(toolName)?.id || toolName,
229	            toolName,
230	            targetResources: [],
231	            success: false,
232	            output: "",
233	            error: check.reason || "SKILL_INTEGRITY",
234	            durationMs: 0,
235	            candidateMutated: false,
236	            status: "DENIED",
237	            denialReason: "SKILL_INTEGRITY",
238	            timestamp: new Date().toISOString(),
239	            simulated: Boolean(this.config.dryRun),
240	            ...skillAttr(),
241	          }),
242	          shouldExit: false,
243	        };
244	      }
245	    }
246	  }
247	
248	  try {
249	    const isPublicEgress = ["search_web", "fetch_web", "browser_navigate", "browser_type"].includes(toolName);
250	    if (!isPublicEgress) {
251	      const serialized = JSON.stringify(args);
252	      const restored = this.securityManager.getVault().restore(serialized, { isAuthorizedSink: true });
253	      if (restored !== serialized) {
254	        args = JSON.parse(restored);
255	      }
256	    }
257	  } catch {}
258	
259	  if (this.flightRecorder) {
260	    this.flightRecorder.recordToolCall(currentStep, call.id, toolName, args);
261	  }
262	
263	  // Safety guard against dangerous deletion targets: denied before dispatch or any approval prompt.
264	  const refusedDeletion = toolName === "delete_file" ? forbiddenDeletion(this.config.workspace, String(args.path || "")) : null;
265	  if (refusedDeletion) {
266	    return {
267	      receipt: {
268	        invocationId: call.id,
269	        taskId: this.activeWorktree?.taskId || this.currentTaskId,
270	        actor,
271	        executionDomain: actor === "subagent" ? "subagent" : "agent_orchestration",
272	        capabilityId: this.capabilityRegistry.getByToolName(toolName)?.id || "fs_delete",
273	        toolName,
274	        targetResources: extractTargetResources(toolName, args),
275	        success: false,
276	        output: "",
277	        error: `${refusedDeletion}.`,
278	        durationMs: 0,
279	        candidateMutated: false,
280	        status: "DENIED",
281	        timestamp: new Date().toISOString(),
282	        simulated: Boolean(this.config.dryRun),
283	      },
284	      shouldExit: false,
285	    };
286	  }
287	
288	  return { args };
289	}
