298	export function decideToolCall(this: any, input: ToolApprovalState): ToolApprovalDecision {
299	  const { call, currentStep, actor, onConfirm, toolName, args, dispatch, subject, skillAttr, recordReceipt } = input;
300	  const cap = this.capabilityRegistry.getByToolName(toolName);
301	  // Tools outside the registry (MCP servers, plugins) are treated as running code: review mode asks before them.
302	  const effect: EffectClass = cap ? cap.effect : READ_ONLY_TOOLS.has(toolName) ? "read_workspace" : "exec";
303	  const egressOrigin = effect === "egress" ? egressOriginOf(toolName, args) : undefined;
304	  const isTrusted = isWorkspaceTrusted(this.config.workspace, this.isReadOnly());
305	  const mode = this.getApprovalMode();
306	  if (this.checkpointReadOnlyFallback && ["egress", "delegate", "context_inject", "write_workspace"].includes(effect)) {
307	    const cancelMsg = `Read-only fallback: ${toolName} is disabled because the workspace could not be safely checkpointed.`;
308	    if (this.flightRecorder) {
309	      this.flightRecorder.recordToolResult(
310	        currentStep,
311	        call.id,
312	        toolName,
313	        false,
314	        cancelMsg,
315	        0,
316	        "CHECKPOINT_READ_ONLY_FALLBACK"
317	      );
318	    }
319	    this.observer?.onToolEnd?.({ dispatch, callId: call.id, tool: toolName, success: false, output: "", error: cancelMsg });
320	    return {
321	      receipt: {
322	        invocationId: call.id,
323	        taskId: this.activeWorktree?.taskId || this.currentTaskId,
324	        actor,
325	        executionDomain: actor === "subagent" ? "subagent" : "agent_orchestration",
326	        capabilityId: cap?.id || toolName,
327	        toolName,
328	        targetResources: extractTargetResources(toolName, args),
329	        success: false,
330	        output: "",
331	        error: cancelMsg,
332	        durationMs: 0,
333	        candidateMutated: false,
334	        status: "DENIED",
335	        denialReason: "CHECKPOINT_READ_ONLY_FALLBACK",
336	        timestamp: new Date().toISOString(),
337	        simulated: Boolean(this.config.dryRun),
338	      },
339	      shouldExit: false,
340	    };
341	  }
342	  // WP-GS-04: optional confirm on workspace skill activation (isUntrustedSource).
343	  let activateIsUntrustedSource = false;
344	  if (toolName === "activate_skill" && skillConfirmWorkspaceEnabled()) {
345	    const named = typeof args?.name === "string" ? this.skillManager.getSkill(args.name) : null;
346	    activateIsUntrustedSource = Boolean(named?.isWorkspaceSkill);
347	  }
348	  const verificationSecurity = this.bridge.getSecurityManager();
349	  // GV-1: the effective policy of this workspace. Its command prefixes and `approval.require_human` ask in every mode,
350	  // and the approval settings are clamped here whatever built this agent's configuration.
351	  const managed: EffectivePolicy = verificationSecurity.getEffectivePolicy();
352	  const managedCommand = toolName === "run_command" && typeof args.command === "string" ? decideManagedCommand(managed, splitSubcommands(args.command)) : undefined;
353	  const human: HumanRequirement | undefined = managedCommand?.decision === "prompt" ? { message: managedCommand.message, source: managedCommand.source } : humanRequirementForEffect(managed, effect);
354	  const askedContext: PolicyContext = {
355	    mode,
356	    trusted: isTrusted,
357	    sandbox: this.config.sandbox,
358	    approvedEgressOrigins: this.approvedEgressOrigins,
359	    egressOrigin,
360	    fullAccess: Boolean(this.config.fullAccess) && !this.isReadOnly(),
361	    isUntrustedSource: activateIsUntrustedSource,
362	  };
363	  const policyContext: PolicyContext = clampApprovalSettings(managed, askedContext, human);
364	  const policyDenial = (cancelMsg: string, denialReason: string) => {
365	    if (this.flightRecorder) this.flightRecorder.recordToolResult(currentStep, call.id, toolName, false, cancelMsg, 0, denialReason);
366	    this.observer?.onToolEnd?.({ dispatch, callId: call.id, tool: toolName, success: false, output: "", error: cancelMsg, denied: true });
367	    return {
368	      receipt: {
369	        invocationId: call.id,
370	        taskId: this.activeWorktree?.taskId || this.currentTaskId,
371	        actor,
372	        executionDomain: actor === "subagent" ? "subagent" : "agent_orchestration",
373	        capabilityId: this.capabilityRegistry.getByToolName(toolName)?.id || "unknown",
374	        toolName,
375	        targetResources: extractTargetResources(toolName, args),
376	        success: false,
377	        output: "",
378	        error: cancelMsg,
379	        durationMs: 0,
380	        candidateMutated: false,
381	        status: "DENIED",
382	        denialReason,
383	        timestamp: new Date().toISOString(),
384	        simulated: Boolean(this.config.dryRun),
385	      } as ExecutionReceipt,
386	      shouldExit: false,
387	    };
388	  };
389	  if (managedCommand?.decision === "forbidden") {
390	    return policyDenial(`Error: ${managedCommand.message} It is not run in any mode. Do the work another way, or report what you could not do.`, "MANAGED_POLICY_FORBIDDEN");
391	  }
392	  // A managed `egress.allowed_domains` decides the destination a call names. The project's own list keeps its existing
393	  // check in the fetch tool; here the merged list applies as the policy library matches it.
394	  if (effect === "egress" && typeof args.url === "string" && managed.egress.allowed_domains.tiers.some((tier) => tier.source.tier !== "project")) {
395	    let hostName = "";
396	    try {
397	      hostName = new URL(args.url).hostname;
398	    } catch {
399	      // A destination that cannot be read cannot be shown to be on the list.
400	    }
401	    if (!hostName) {
402	      return policyDenial(`Error: '${String(args.url).slice(0, 120)}' is not a URL whose host can be checked against the managed allowlist (egress.allowed_domains). ${describeSource(managed.egress.allowed_domains.source)}`, "MANAGED_POLICY_EGRESS");
403	    }
404	    const reachable = permitsEgressHost(managed, hostName);
405	    if (!reachable.allowed) return policyDenial(`Error: ${reachable.message}`, "MANAGED_POLICY_EGRESS");
406	  }
407	  // DV-3: a test edited through the shell is recorded against the obligation that names it (the CS-2 snapshot and diff).
408	  verificationSecurity.setShellChangeObserver(this.objective?.obligations?.length ? (changes: VerificationShellChange[], scan: { complete: boolean }) => {
409	    if (!this.objective) return;
410	    if (!scan.complete) {
411	      recordUnverifiableTestEdit(this.objective, "<workspace-scan>", "The bounded shell snapshot did not cover the entire workspace; verification-file edits may be missing.");
412	    }
413	    for (const c of changes) {
414	      if (c.class !== "test_file") continue;
415	      if (c.beforeText === undefined) {
416	        recordUnverifiableTestEdit(this.objective, c.path, "The changed test file exceeded the retained snapshot size, so weakening could not be assessed.");
417	        continue;
418	      }
419	      recordTestEdit(this.objective, { path: c.path, before: c.beforeText, after: c.afterText ?? "" });
420	    }
421	  } : undefined);
422	  const verificationAuthority: VerificationEditContext = { role: this.role, fullAccess: policyContext.fullAccess, operator: Boolean(onConfirm) };
423	  let verificationEdit = verificationSecurity.verificationEditDecision(toolName, args, verificationAuthority);
424	  let verificationQuestion: NeedsInputQuestion | undefined;
425	  if (verificationEdit?.action === "deny" && verificationEdit.needsDecision) {
426	    // VC-9: nobody to ask. An answer from a previous blocked run settles it; otherwise the turn ends BLOCKED with the question.
