428	      "verification_edit",
429	      `Allow ${toolName} to change ${verificationEdit.path} (${verificationEdit.class}, rule '${verificationEdit.rule}')?`,
430	      { tool: toolName, path: verificationEdit.path, class: verificationEdit.class },
431	      toolName,
432	      verificationEdit.path,
433	      verificationEdit.class,
434	    );
435	    if (this.headlessDecision(verificationQuestion) === "approve") {
436	      verificationAuthority.approved = { path: verificationEdit.path };
437	      verificationEdit = verificationSecurity.verificationEditDecision(toolName, args, verificationAuthority);
438	      verificationQuestion = undefined;
439	    }
440	  }
441	  if (verificationEdit?.action === "deny") {
442	    const declined = verificationQuestion && this.operatorAnswers.get(verificationQuestion.id) === "decline";
443	    const cancelMsg = verificationSecurity.refuseVerificationEdit(verificationEdit, toolName, this.role).error
444	      + (verificationQuestion ? (declined ? " The operator declined this edit." : ` needs_input ${verificationQuestion.id}: the run ends BLOCKED so the operator can decide.`) : "");
445	    this.syncVerificationAttempts();
446	    if (this.flightRecorder) {
447	      this.flightRecorder.recordToolResult(currentStep, call.id, toolName, false, cancelMsg, 0, VERIFICATION_CONFIG_PROTECTED);
448	    }
449	    this.observer?.onToolEnd?.({ dispatch, callId: call.id, tool: toolName, success: false, output: "", error: cancelMsg });
450	    return {
451	      receipt: {
452	        invocationId: call.id,
453	        taskId: this.activeWorktree?.taskId || this.currentTaskId,
454	        actor,
455	        executionDomain: actor === "subagent" ? "subagent" : "agent_orchestration",
456	        capabilityId: this.capabilityRegistry.getByToolName(toolName)?.id || "unknown",
457	        toolName,
458	        targetResources: extractTargetResources(toolName, args),
459	        success: false,
460	        output: "",
461	        error: cancelMsg,
462	        durationMs: 0,
463	        candidateMutated: false,
464	        status: "DENIED",
465	        denialReason: VERIFICATION_CONFIG_PROTECTED,
466	        timestamp: new Date().toISOString(),
467	        simulated: Boolean(this.config.dryRun),
468	      },
469	      shouldExit: false,
470	    };
471	  }
472	  // CS-9: the operator's command rules. `forbidden` refuses in every mode; `prompt` asks unless --yes; `allow` removes the
473	  // normal prompt only (every other control below still applies). The deciding rule is recorded for the session export.
474	  if (this.commandRulesNotice) {
475	    // The file is refused whole (unchanged); the notice says what that costs, so a dropped `forbidden` is not a surprise.
476	    const notice = `[nexus] command_rules: ${this.commandRulesNotice} Its forbidden and prompt rules are NOT enforced until the file is fixed.`;
477	    this.commandRulesNotice = undefined;
478	    if (this.depth === 0) {
479	      if (this.observer?.onNotice) this.observer.onNotice(notice);
480	      else console.warn(notice);
481	    }
482	  }
483	  const operatorVerdict: CommandVerdict | null = toolName === "run_command" && typeof args.command === "string" ? decideCommand(this.commandRules, args.command) : null;
484	  // GV-1 `commands.disable_allow_rules`: the operator's `allow` rules are not used; `prompt` and `forbidden` keep working.
485	  const ruleVerdict = operatorVerdict?.decision === "allow" && managed.commands.disable_allow_rules.value ? null : operatorVerdict;
486	  const recordRule = (verdict: CommandVerdict, effectText: CommandRuleDecision["effect"]): void => {
487	    this.commandRuleDecisions.push({
488	      timestamp: new Date().toISOString(),
489	      tool: toolName,
490	      command: redactSecrets(String(args.command)).replace(/\s+/g, " ").slice(0, 200),
491	      decision: verdict.decision,
492	      effect: effectText,
493	      rule: verdict.rule.index,
494	      rules: verdict.rules.map((r) => r.index),
495	      prefix: describePrefix(verdict.rule),
496	      ...(verdict.rule.justification ? { justification: verdict.rule.justification } : {}),
497	    });
498	    if (this.commandRuleDecisions.length > 500) this.commandRuleDecisions.splice(0, this.commandRuleDecisions.length - 500);
