5	
6	export async function dispatchToolCallImpl(this: any, call: ToolCall,
7	    currentStep: number,
8	    actor: "agent" | "subagent" = "agent",
9	    onConfirm?: ConfirmHandler): Promise<{ receipt: ExecutionReceipt; shouldExit: boolean }> {
