25	  const subject = String(args.path ?? args.file_path ?? args.command ?? args.url ?? args.query ?? "").replace(/\s+/g, " ").slice(0, 120);
26	  this.activity("tool", { tool: toolName, ...(subject ? { subject } : {}) });
