const scrub = (s: string): string => s.split(world.repo).join("<ws>").split(world.home).join("<home>").split(world.stateDir).join("<state>").replace(/needs_input [0-9a-f]{8,}/g, "needs_input <id>").replace(/\b[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\b/g, "<uuid>");

type Op = "none" | "approves" | "declines";
async function run(agent: AutonomousAgent, probe: ReturnType<typeof instrument>, name: string, raw: unknown, op: Op, actor: "agent" | "subagent" = "agent", obs: string[] = []): Promise<any> {
  const a = agent as any;
  const asked: string[] = [];
  const onConfirm = op === "none" ? undefined : async (tool: string, args: unknown, _s: unknown, options?: unknown) => {
    asked.push(`${tool} ${scrub(JSON.stringify(args))} ${JSON.stringify(options ?? null)}`);
    probe.trace("confirm");
    return op === "approves";
  };
  const call = { id: `p-${++seq}`, type: "function", function: { name, arguments: typeof raw === "string" ? raw : JSON.stringify(raw) } };
  const logs: string[] = [];
  console.log = (...x: any[]) => { logs.push(scrub(x.join(" "))); probe.trace("console"); };
  console.warn = (...x: any[]) => { logs.push("W:" + scrub(x.join(" "))); };
  probe.take();
  let res: any, thrown: string | null = null;
  try { res = await a.dispatchToolCall(call, 1, actor, onConfirm); } catch (e) { thrown = `${(e as Error).name}: ${(e as Error).message}`; }
  console.log = realLog; console.warn = realWarn;
  const trace = probe.take().join(">");
  const r = res?.receipt;
  const rec = r ? Object.fromEntries(Object.entries(r).filter(([k]) => !["timestamp", "durationMs", "invocationId", "taskId"].includes(k)).sort()) : null;
  const state = {
    lastReceipts: a.lastToolReceipts?.length ?? 0, turnDenials: a.turnDenials, egress: [...(a.approvedEgressOrigins ?? [])].sort(),
    rules: (a.commandRuleDecisions ?? []).map((d: any) => ({ ...d, timestamp: undefined })),
    modified: [...(a.modifiedFiles ?? [])].map((f: string) => scrub(f)).sort(), evalReceipts: a.evaluationToolReceipts?.length ?? 0,
    dispatchSeq: a.toolDispatchSeq, opSeq: a.operationSeq, pending: a.pendingNeedsInput ? scrub(JSON.stringify({ ...a.pendingNeedsInput, id: undefined })) : null,
    subQ: a.subagentQuestions?.length ?? 0, groups: [...a.enabledToolGroups].sort(), bg: a.turnBackgroundCommands, conv: Boolean(a.turnConvergence),
    interrupted: Boolean(a.interruptedCall), verAttempts: a.objective?.verification?.length ?? 0,
  };
  return { thrown, shouldExit: res?.shouldExit, receipt: rec ? JSON.parse(scrub(JSON.stringify(rec))) : null, asked, logs, trace, state };
}

